   if a[1]==b[1] and a[2]=='RMSprop' and a[3]>=.001 and b[2] in ['Adam','AdamW'] and b[3]<=.0003 and a[0] in order and b[0] in order:
    pairs.append((h['question_id'],a,b,order.index(b[0])<order.index(a[0]),re.search(r'training_steps: (\d+)',h['question']).group(1)))
